# Acceptance table for the correction run. Literals are written here.
# Chooser title is null. The header glyph hash is separate from the help sentence.
# Do not edit this file after it has run.
import json
from pathlib import Path

ROOT = Path('.')
SRC = ROOT / 'work/scripts/accept_table_k1.json'
DEST = ROOT / 'work/scripts/accept_table_c1.json'
HEADER = 'bd8da5bd11491b59d2ddcf2c60e77cc4a115d4ce3a1b1dfffc4f0173e2280477'
PAGE = '@A02C@@A065@AF Button'
ROW = '@A040@AF Target Mode'
HELP = 'Choose the AF target area.'
HALF = [0x0e, 0x02, 0x03, 0x00, 0x03, 0x00, 0x03, 0x00, 0x00, 0x00]
SINGLE = [0x0e, 0x02, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00]
SMALL = [0x0e, 0x02, 0x03, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00]
ALL = [0x0e, 0x02, 0x02, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00]
STOCK = [0x0e, 0x02, 0x02, 0x00, 0x1b, 0x00, 0x27, 0x00, 0x00, 0x00]
OWNERS = [1, 0, 2, 0, 1, 2, 1, 0, 2, 2, 2, 0]
HALF_AT = {0, 1, 3, 4, 6, 7, 11}
EDGES = [
    ('s1', 'down'), ('s1', 'up'),
    ('afon', 'down'), ('afon', 'up'),
    ('s1', 'down'), ('afon', 'down'), ('afon', 'up'), ('s1', 'up'),
    ('afon', 'down'), ('s1', 'down'), ('s1', 'up'), ('afon', 'up'),
]
CELLS = {
    'k90a1': [1, 1],
    'k1dd1': [3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
    'k99a1': [2, 0, 2, 0, 2, 0, 5, 5],
    'k9a41': 0,
    'k5962': [526, 526, 526, 526, 526, 526],
    'home': {
        '0x99d2': [526, 526, 526], '0x9fa1': [0, 0, 0], '0xdfa1': [0], '0x1ea1': [0],
        '0x9ec1': [0], '0x9ed1': [1], '0x9ee1': [0], '0x9ef1': [0], '0x59b1': [0],
    },
}


def menu(title, highlight, profile, screen, help_text, slot, help_id, glyph, header):
    return {
        'title': title,
        'highlight': highlight,
        'invariant': True,
        'helpText': help_text,
        'headerHash': header,
        'assertTitle': True,
        'readback': {
            'profile': profile,
            'profileCached': profile,
            'k90a1': [1, 1],
            'screen': screen,
            'slotValue': slot,
            'helpId': help_id,
            'glyph': glyph,
            'cells': None,
        },
    }


def add(steps, id_, who, phase, expect, key=None, action=None, direction=None):
    steps.append({
        'id': id_,
        'who': who,
        'phase': phase,
        'key': key,
        'dir': direction,
        'action': action,
        'controlStep': id_ if who == 'both' else None,
        'expect': expect,
    })


def main():
    src = json.loads(SRC.read_text(encoding='utf-8'))
    steps = []
    for step in src:
        if step['id'] == 'zone-row':
            break
        expect = step['expect']
        if expect.get('title') == 'glyph-header':
            expect['title'] = None
            expect['headerHash'] = HEADER
        else:
            expect['headerHash'] = None
        expect['assertTitle'] = True
        steps.append({
            'id': step['id'],
            'who': 'both',
            'phase': 'menu-a',
            'key': step.get('key'),
            'dir': None,
            'action': step.get('action'),
            'controlStep': step['id'],
            'expect': expect,
        })

    add(steps, 'a-zone-row', 'candidate', 'menu-a', menu(PAGE, ROW, 0, 'menu', None, None, None, {'value': 0, 'id': 9123}, None), key='down')
    add(steps, 'a-zone-open', 'candidate', 'menu-a', menu(None, 9123, 0, 'menu', HELP, 0, 424, None, HEADER), key='ok')
    add(steps, 'a-zone-right', 'candidate', 'menu-a', menu(None, 1610, 0, 'menu', HELP, 1, 424, None, HEADER), key='right')
    add(steps, 'a-commit', 'candidate', 'menu-a', menu(PAGE, ROW, 1, 'menu', None, 1, 424, {'value': 1, 'id': 1610}, None), key='ok')
    add(steps, 'a-exit-0', 'candidate', 'menu-a', menu('2.AF', PAGE, 1, 'menu', None, None, None, None, None), key='menu')
    add(steps, 'a-exit-1', 'candidate', 'menu-a', menu('Y/M/D', None, 1, 'shooting', None, None, None, None, None), key='menu')

    add(steps, 'a-leave-0', 'control', 'menu-a', menu('2.AF', PAGE, 255, 'menu', None, None, None, None, None), key='menu')
    add(steps, 'a-leave-1', 'control', 'menu-a', menu('Y/M/D', None, 255, 'shooting', None, None, None, None, None), key='menu')

    for index, (key, direction) in enumerate(EDGES):
        zone = HALF if index in HALF_AT else SINGLE
        steps.append({
            'id': f'edge-a-{index}',
            'who': 'both',
            'phase': 'edges-a',
            'key': key,
            'dir': direction,
            'action': 'edge',
            'controlStep': f'edge-a-{index}',
            'expect': {
                'assertTitle': False,
                'screen': 'shooting',
                'target': zone,
                'targetControl': STOCK,
                'owner': OWNERS[index],
                'profile': 1,
                'profileControl': 255,
                'focus': 0,
                'subject': 0,
                'cells': CELLS,
                'invariant': True,
            },
        })

    add(steps, 'b-menu', 'candidate', 'menu-b', menu('2.AF', PAGE, 1, 'menu', None, None, None, None, None), key='menu')
    add(steps, 'b-enter', 'candidate', 'menu-b', menu(PAGE, '@A066@ Priority', 1, 'menu', None, None, None, {'value': 1, 'id': 1610}, None), key='ok')
    add(steps, 'b-down-1', 'candidate', 'menu-b', menu(PAGE, '@A066@ Priority', 1, 'menu', None, None, None, {'value': 1, 'id': 1610}, None), key='down')
    add(steps, 'b-zone-row', 'candidate', 'menu-b', menu(PAGE, ROW, 1, 'menu', None, None, None, {'value': 1, 'id': 1610}, None), key='down')
    add(steps, 'b-open', 'candidate', 'menu-b', menu(None, 1610, 1, 'menu', HELP, 1, 424, None, HEADER), key='ok')
    add(steps, 'b-right', 'candidate', 'menu-b', menu(None, 650, 1, 'menu', HELP, 2, 424, None, HEADER), key='right')
    add(steps, 'b-commit', 'candidate', 'menu-b', menu(PAGE, ROW, 2, 'menu', None, 2, 424, {'value': 2, 'id': 650}, None), key='ok')
    add(steps, 'b-exit-0', 'candidate', 'menu-b', menu('2.AF', PAGE, 2, 'menu', None, None, None, None, None), key='menu')
    add(steps, 'b-exit-1', 'candidate', 'menu-b', menu('Y/M/D', None, 2, 'shooting', None, None, None, None, None), key='menu')

    add(steps, 'b-menu', 'control', 'menu-b', menu('2.AF', PAGE, 255, 'menu', None, None, None, None, None), key='menu')
    add(steps, 'b-enter', 'control', 'menu-b', menu(PAGE, '@A066@ Priority', 255, 'menu', None, None, None, None, None), key='ok')
    add(steps, 'b-leave-0', 'control', 'menu-b', menu('2.AF', PAGE, 255, 'menu', None, None, None, None, None), key='menu')
    add(steps, 'b-leave-1', 'control', 'menu-b', menu('Y/M/D', None, 255, 'shooting', None, None, None, None, None), key='menu')

    for index, (key, direction) in enumerate(EDGES):
        zone = HALF if index in HALF_AT else SMALL
        steps.append({
            'id': f'edge-b-{index}',
            'who': 'both',
            'phase': 'edges-b',
            'key': key,
            'dir': direction,
            'action': 'edge',
            'controlStep': f'edge-b-{index}',
            'expect': {
                'assertTitle': False,
                'screen': 'shooting',
                'target': zone,
                'targetControl': STOCK,
                'owner': OWNERS[index],
                'profile': 2,
                'profileControl': 255,
                'focus': 0,
                'subject': 0,
                'cells': CELLS,
                'invariant': True,
            },
        })

    loose = {
        'a-exit-0', 'a-exit-1', 'a-leave-0', 'a-leave-1',
        'b-menu', 'b-enter', 'b-down-1', 'b-zone-row', 'b-exit-0', 'b-exit-1',
        'b-leave-0', 'b-leave-1',
    }
    for step in steps:
        if step['id'] in loose and step['phase'].startswith('menu'):
            step['expect']['assertGlyph'] = False
            step['expect']['assertFaces'] = False

    add(steps, 'save', 'both', 'save', {
        'assertTitle': False,
        'screen': 'shooting',
        'invariant': True,
    }, action='save')

    add(steps, 'reopen-base', 'both', 'reopen', {
        'assertTitle': False,
        'screen': 'shooting',
        'profile': 0,
        'profileControl': 255,
        'focus': 0,
        'subject': 0,
        'cells': CELLS,
    }, action='reopen-base')
    add(steps, 'reopen-afon', 'both', 'reopen', {
        'assertTitle': False,
        'screen': 'shooting',
        'target': ALL,
        'targetControl': STOCK,
        'owner': 2,
        'profile': 0,
        'profileControl': 255,
        'focus': 0,
        'subject': 0,
        'cells': CELLS,
    }, action='reopen-edge', key='afon', direction='down')

    DEST.write_text(json.dumps(steps, indent=2) + '\n', encoding='utf-8')
    print('steps', len(steps))


if __name__ == '__main__':
    main()
